function seedSessionsAndAttendance(db) {
  db.get("SELECT COUNT(*) as count FROM sessions", (err, row) => {
    if (!err && row && row.count < 10) {
      console.log("📅 Seeding Complete Baseline Classroom Sessions (" + BASELINE_SESSIONS.length + " sessions)...");
      const sesStmt = db.prepare("INSERT OR REPLACE INTO sessions (id, school_id, class_id, trainer_id, date, time, topic, status, notes, is_locked) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)");
      BASELINE_SESSIONS.forEach(s => {
        sesStmt.run(s.id, s.school_id, s.class_id, s.trainer_id, s.date, s.time, s.topic, s.status, s.notes, s.is_locked);
      });
      sesStmt.finalize();
    }
  });

  db.get("SELECT COUNT(*) as count FROM attendance", (err, row) => {
    if (!err && row && row.count === 0) {
      console.log("📋 Seeding Baseline Attendance Records in SQLite (" + BASELINE_ATTENDANCE.length + " records)...");
      const attStmt = db.prepare("INSERT OR REPLACE INTO attendance (id, session_id, student_id, status) VALUES (?, ?, ?, ?)");
      BASELINE_ATTENDANCE.forEach(a => {
        attStmt.run(a.id, a.session_id, a.student_id, a.status);
      });
      attStmt.finalize();
    }
  });
}

module.exports = {
  seedSessionsAndAttendance,
  BASELINE_SESSIONS,
  BASELINE_ATTENDANCE
};
